function solve(a, b, c, c1, c2) {
  // f(n) = a·n² + b·n + c. Catat n terakhir yang melanggar c1·n² ≤ f(n) ≤ c2·n².
  let terakhirMelanggar = 0
  for (let n = 1; n <= 1000; n++) {
    const f = a * n * n + b * n + c
    if (f < c1 * n * n || f > c2 * n * n) terakhirMelanggar = n
  }
  // Masih melanggar di n = 1000: dengan c1 dan c2 ini syaratnya tidak akan terpenuhi.
  if (terakhirMelanggar === 1000) return -1
  return terakhirMelanggar + 1
}
